<template>
  <el-dialog
    v-model="visible"
    :title="isEdit ? t('nodes.editNode') : t('nodes.createNode')"
    width="560px"
    :close-on-click-modal="false"
    @closed="onClosed"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="100px">
      <el-form-item :label="t('common.name')" prop="name">
        <el-input v-model="form.name" :placeholder="t('nodes.namePlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('nodes.host')">
        <el-input v-model="form.host" :placeholder="t('common.optional')" />
      </el-form-item>
      <el-form-item :label="t('nodes.platform')">
        <el-radio-group v-model="form.platform">
          <el-radio value="linux">Linux</el-radio>
          <el-radio value="windows">Windows</el-radio>
        </el-radio-group>
      </el-form-item>
      <el-form-item :label="t('nodes.description')">
        <el-input v-model="form.description" type="textarea" :rows="3" :placeholder="t('common.optional')" />
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="visible = false">{{ t('common.cancel') }}</el-button>
      <el-button type="primary" :loading="submitting" @click="onSubmit">
        {{ isEdit ? t('common.save') : t('common.create') }}
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { createNode, updateNode, type NodeRead, type NodeCreate } from '@/api/nodes'
import { showError } from '@/utils/error'

const { t } = useI18n()

const props = defineProps<{
  modelValue: boolean
  node?: NodeRead | null
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
  success: [node: NodeRead]
}>()

const visible = ref(props.modelValue)
const submitting = ref(false)
const formRef = ref<FormInstance>()

const form = ref<NodeCreate>({
  name: '',
  host: '',
  description: '',
  platform: 'linux',
})

const isEdit = ref(false)

const rules: FormRules = {
  name: [{ required: true, message: () => t('nodes.nameRequired'), trigger: 'blur' }],
}

watch(
  () => props.modelValue,
  (val) => {
    visible.value = val
  }
)

watch(
  () => props.node,
  (node) => {
    if (node) {
      isEdit.value = true
      form.value = {
        name: node.name,
        host: node.host || '',
        description: node.description || '',
        platform: node.platform,
      }
    } else {
      isEdit.value = false
      form.value = { name: '', host: '', description: '', platform: 'linux' }
    }
  },
  { immediate: true }
)

function onClosed() {
  emit('update:modelValue', false)
  formRef.value?.resetFields()
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const data: NodeCreate = {
      ...form.value,
      host: form.value.host || undefined,
      description: form.value.description || undefined,
    }
    const node = props.node
      ? await updateNode(props.node.id, data)
      : await createNode(data)
    ElMessage.success(isEdit.value ? t('nodes.nodeUpdated') : t('nodes.nodeCreated'))
    emit('success', node)
    visible.value = false
  } catch (error) {
    showError(error, isEdit.value ? t('nodes.updateFailed') : t('nodes.createFailed'))
  } finally {
    submitting.value = false
  }
}
</script>
