<template>
  <div class="page-node-list">
    <CrudToolbar :title="t('nodes.title')" :create-text="t('nodes.createNode')" :can-create="authStore.isAdmin" @create="onCreate" />

    <el-alert
      v-if="errorMessage"
      :title="errorMessage"
      type="error"
      show-icon
      closable
      @close="errorMessage = ''"
      style="margin-bottom: 16px"
    />

    <el-card style="margin-bottom: 16px">
      <el-form :inline="true" :model="filters">
        <el-form-item :label="t('nodes.group')">
          <el-input v-model="filters.group" :placeholder="t('nodes.groupPlaceholder')" clearable />
        </el-form-item>
        <el-form-item :label="t('nodes.labelKey')">
          <el-input v-model="filters.label_key" :placeholder="t('nodes.labelKeyPlaceholder')" clearable />
        </el-form-item>
        <el-form-item :label="t('nodes.labelValue')">
          <el-input v-model="filters.label_value" :placeholder="t('nodes.labelValuePlaceholder')" clearable />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="onSearch">{{ t('common.query') }}</el-button>
          <el-button @click="onResetFilter">{{ t('common.reset') }}</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <el-card>
      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="nodes"
        :loading="loading"
        :server-side="true"
        :total="total"
      >
        <el-table-column prop="node_id" :label="t('nodes.nodeId')" min-width="180" />
        <el-table-column prop="name" :label="t('common.name')" min-width="140" />
        <el-table-column prop="group" :label="t('nodes.group')" min-width="120" />
        <el-table-column prop="status" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <StatusTag :status="row.status" type="node" />
          </template>
        </el-table-column>
        <el-table-column prop="last_seen" :label="t('nodes.lastSeen')" min-width="160">
          <template #default="{ row }">
            {{ row.last_seen ? formatTime(row.last_seen) : '-' }}
          </template>
        </el-table-column>
        <el-table-column prop="is_local" :label="t('nodes.isLocal')" width="100">
          <template #default="{ row }">
            <el-tag v-if="row.is_local" type="info" size="small">{{ t('common.yes') }}</el-tag>
            <span v-else>-</span>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="240" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="showInstallCommand(row)">
              {{ t('nodes.installCommand') }}
            </el-button>
            <template v-if="authStore.isAdmin">
              <el-button link type="primary" size="small" @click="onResetToken(row)">
                {{ t('nodes.resetToken') }}
              </el-button>
              <ConfirmButton
                :title="t('nodes.confirmDelete')"
                confirm-button-type="danger"
                @confirm="onDelete(row)"
              >
                <el-button link type="danger" size="small" :disabled="row.is_local">
                  {{ t('common.delete') }}
                </el-button>
              </ConfirmButton>
            </template>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <NodeFormDialog v-model="dialogVisible" @success="onFormSuccess" />

    <el-dialog v-model="installDialogVisible" :title="t('nodes.installCommandTitle')" width="680px">
      <p style="margin-bottom: 12px">
        {{ t('nodes.platformColon') }}
        <el-radio-group v-model="installPlatform">
          <el-radio value="linux">Linux</el-radio>
          <el-radio value="windows">Windows</el-radio>
        </el-radio-group>
      </p>
      <CodeEditor
        v-model="installCommand"
        :rows="6"
        :placeholder="t('nodes.noInstallCommand')"
        disabled
      />
      <template #footer>
        <el-button @click="installDialogVisible = false">{{ t('common.close') }}</el-button>
        <el-button type="primary" @click="copyInstallCommand">{{ t('common.copy') }}</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import { deleteNode, getInstallCommand, getNodes, resetNodeToken, type NodeInstallInfo, type NodeRead } from '@/api/nodes'
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import { useListQuery } from '@/composables/useListQuery'
import StatusTag from '@/components/common/StatusTag.vue'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import NodeFormDialog from './NodeFormDialog.vue'
import CodeEditor from '@/components/common/CodeEditor.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'
import { copyToClipboard } from '@/utils/clipboard'

const { t } = useI18n()
const authStore = useAuthStore()

const nodes = ref<NodeRead[]>([])
const total = ref(0)
const loading = ref(false)
const errorMessage = ref('')
const dialogVisible = ref(false)
const installDialogVisible = ref(false)
const installPlatform = ref<'linux' | 'windows'>('linux')
const installInfo = ref<NodeInstallInfo | null>(null)
// 随平台切换实时计算，否则对话框内切换 Linux/Windows 时内容不更新
const installCommand = computed(() => {
  if (!installInfo.value) return ''
  return installPlatform.value === 'linux'
    ? installInfo.value.linux_command
    : installInfo.value.windows_command
})

const { page, pageSize, filters, resetFilters } = useListQuery({
  defaults: {
    group: '',
    label_key: '',
    label_value: '',
  },
  parse: (q) => ({
    group: (q.group as string) || '',
    label_key: (q.label_key as string) || '',
    label_value: (q.label_value as string) || '',
  }),
  serialize: (f) => ({
    group: f.group || undefined,
    label_key: f.label_key || undefined,
    label_value: f.label_value || undefined,
  }),
})

async function loadNodes() {
  loading.value = true
  errorMessage.value = ''
  try {
    const response = await getNodes({
      page: page.value,
      page_size: pageSize.value,
      group: filters.group || undefined,
      label_key: filters.label_key || undefined,
      label_value: filters.label_value || undefined,
    })
    nodes.value = response.items
    total.value = response.total
  } catch (error) {
    errorMessage.value = t('nodes.loadFailed')
    showError(error, errorMessage.value)
  } finally {
    loading.value = false
  }
}

function onSearch() {
  page.value = 1
  // 状态变化会自动触发加载
}

function onResetFilter() {
  resetFilters()
  // 状态变化会自动触发加载
}

function onCreate() {
  dialogVisible.value = true
}

function onFormSuccess() {
  loadNodes()
}

async function showInstallCommand(row: NodeRead) {
  try {
    installInfo.value = await getInstallCommand(row.id)
    installDialogVisible.value = true
  } catch (error) {
    showError(error, t('nodes.getInstallCommandFailed'))
  }
}

async function onResetToken(row: NodeRead) {
  try {
    await resetNodeToken(row.id)
    ElMessage.success(t('nodes.tokenResetSuccess'))
    loadNodes()
  } catch (error) {
    showError(error, t('nodes.resetTokenFailed'))
  }
}

async function onDelete(row: NodeRead) {
  if (row.is_local) {
    ElMessage.warning(t('nodes.localNodeCannotDelete'))
    return
  }
  try {
    await deleteNode(row.id)
    ElMessage.success(t('nodes.nodeDeleted'))
    loadNodes()
  } catch (error) {
    showError(error, t('nodes.deleteFailed'))
  }
}

function copyInstallCommand() {
  copyToClipboard(installCommand.value)
}

function formatTime(value: string) {
  return new Date(value).toLocaleString()
}

useRealtimeRefresh(loadNodes, ['nodes'], { notifyEventTypes: ['node.online', 'node.offline'] })

// 分页、筛选、URL query 变化时统一触发加载；immediate 确保首次进入自动加载
watch(
  () => ({ page: page.value, pageSize: pageSize.value, filters }),
  loadNodes,
  { deep: true, immediate: true }
)
</script>
